import{_ as o,a0 as a,w as p,s as r,ao as d,I as i,x as s,a1 as l,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"Linux 黑話解釋：什麼是 POSIX？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 黑話解釋：什麼是 POSIX？ | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 黑話解釋：什麼是 POSIX？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 黑話解釋：什麼是 POSIX？ | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20220119 What is POSIX- Why Does it Matter to Linux-UNIX Users","title":"Linux 黑話解釋：什麼是 POSIX？","tag":"202201","desc":""},"relativePath":"202201/20220119 What is POSIX- Why Does it Matter to Linux-UNIX Users.md","filePath":"[post].md"}'),u={name:"202201/20220119 What is POSIX- Why Does it Matter to Linux-UNIX Users.md"};function X(I,t,x,S,m,P){const e=a("Link");return p(),r("div",null,[t[21]||(t[21]=d('<h1 id="linux-黑話解釋-什麼是-posix" tabindex="-1">Linux 黑話解釋：什麼是 POSIX？ <a class="header-anchor" href="#linux-黑話解釋-什麼是-posix" aria-label="Permalink to “Linux 黑話解釋：什麼是 POSIX？”">​</a></h1><p>POSIX，你肯定在各種在線論壇和文章中，聽到過這個縮寫，或讀到過關於它的信息。程序員和系統開發人員似乎最關心這個問題。它聽起來很神秘，雖然有很多關於這個主題的好資料，但一些討論區（簡潔是它們的特點）並沒有詳細説明它是什麼，這可能會讓人困擾。那麼，POSIX 到底是什麼？</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/What-is-POSIX.png?resize=800%2C450&amp;ssl=1" alt=""></p><h3 id="posix-簡介" tabindex="-1">POSIX 簡介 <a class="header-anchor" href="#posix-簡介" aria-label="Permalink to “POSIX 簡介”">​</a></h3><p>與其説 POSIX 是一個東西，不如説是一個標籤。想像一下，有一個盒子，上面貼着標籤：POSIX，而盒子裏是一個標準。該標準由 POSIX 所關注的規則和指令集組成。<strong>POSIX</strong> 是<ruby>可移植操作系統接口<rt>Portable Operating System Interface</rt></ruby> 的縮寫。它是一個 IEEE 1003.1 標準，其定義了應用程序（以及命令列 Shell 和實用程序接口）和 UNIX 操作系統之間的語言接口。</p><p>當 UNIX 程序從一個 UNIX 平台移植到另一個平台時，遵守該標準可以確保其兼容性。POSIX 主要關注的是 AT&amp;T 的 System V UNIX 和 BSD UNIX 的特性。</p><p>該標準必須闡明並遵循如何實現操作系統之間互操作性的目標的規則。POSIX 涵蓋了以下內容：系統接口、命令和實用程序、網絡文件訪問，這裏僅舉幾例（POSIX 的內容遠不止這些）。</p><h3 id="為什麼有-posix" tabindex="-1">為什麼有 POSIX？ <a class="header-anchor" href="#為什麼有-posix" aria-label="Permalink to “為什麼有 POSIX？”">​</a></h3><p>一句話：可移植性。</p><p>60 多年前，如果程序員想讓他們的軟件在一個以上的系統上運行，就必須完全重寫代碼。由於所涉及的費用，這種情況並不經常發生，但在 1960 年代中期，可移植性成為一種特性 —— 不是通過 POSIX，而是在大型機領域。</p><p>IBM 推出了 System/360 系列的大型計算機。不同的型號有其獨特的規範，但硬件使得它們可以使用同一個操作系統：OS/360。</p><p>不僅操作系統可以在不同的型號上運行，應用程序也可以在它們上面運行。這不僅降低了成本，而且創造了“計算機系統”：可以跨產品線協同工作的系統。今天，這一切都很常見，比如網絡和系統，但在當時，這是一個巨大的進步！</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/IBM-system-360-vintage-picture.jpg?resize=800%2C593&amp;ssl=1" alt="IBM System 360 | 圖片來源：IBM"></p><p>大約在同一時間，當 UNIX 出現的時候，它也做出了承諾，它可以在不同製造商的機器上運行。然而，當 UNIX 開始衍生出不同的流派時，在這些 UNIX 變體之間移植代碼變得很困難。UNIX 可移植性的承諾正在失去基礎。</p><p>為了解決這個可移植性問題，在 20 世紀 80 年代形成了 POSIX 標準。這個標準是在 AT&amp;T 的 System V UNIX 和 BSD UNIX 的基礎上定義的，這是當時最大的兩個 UNIX 變體。值得注意的是，POSIX 的形成並不是為了控制操作系統的構建方式，任何公司都可以自由地以他們喜歡的方式設計他們的 UNIX 變體。POSIX 只關心應用程序與操作系統的接口是怎樣的。用程序員的話來説，接口是一個程序的代碼與另一個程序的通信方法。接口期望程序 A 向程序 B 提供特定類型的信息。同樣地，程序 A 期望程序 B 用特定類型的數據來回答。</p><p>例如，如果我想用 <code>cat</code> 命令讀取一個文件，我會在命令列上輸入類似這樣的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat myfile.txt</span></span></code></pre></div><p>我不想説很多程序員的術語，簡單的來説，<code>cat</code> 命令調用操作系統來獲取文件，以便 <code>cat</code> 能夠讀取它。<code>cat</code> 讀取它，然後在屏幕上顯示文件的內容。在應用程序（<code>cat</code>）和操作系統之間有很多的相互作用。這種相互作用如何工作是 POSIX 所關心的。如果這種相互作用在不同的 UNIX 變體中是相同的，那麼可移植性，無論操作系統、製造商和硬件如何，就可以重新獲得了。</p><p>關於如何實現這一切的具體細節，在該標準中作了規定。</p><h3 id="合規是自願的" tabindex="-1">合規是自願的 <a class="header-anchor" href="#合規是自願的" aria-label="Permalink to “合規是自願的”">​</a></h3><p>我們所有人都至少見過這樣的信息：“如需幫助，請輸入：XXXX -help”。這在 Linux 中很常見，但是這不符合 POSIX 標準。POSIX 從來沒有要求雙破折號，他們希望用一個破折號。雙破折號來自 GNU，然而，它並沒有損害 Linux，而且還為其增加了一點特性。同時，Linux 大部分都是兼容 POSIX 的，特別是在涉及到系統調用接口時。這就是為什麼我們能夠在 Linux、Sys V UNIX 和 BSD UNIX 上運行 X、GNOME 和 KDE 應用程序。各種命令，如 <code>ls</code>、<code>cat</code>、<code>grep</code>、<code>find</code>、<code>awk</code> 等，在不同的變體中操作相同。</p>',21)),i("p",null,[t[1]||(t[1]=s("作為一項規則，合規是一個自願的步驟。當代碼符合要求時，移到另一個系統上就比較容易，很少有必要或根本不需要重寫代碼。當代碼可以在不同的系統上工作時，它的使用範圍就會擴大。使用其他系統的人可以從使用該程序中受益。對於初出茅廬的程序員來説，學習如何編寫符合 POSIX 標準的程序，就能對他們的職業生涯有所幫助。對於那些對 Linux 領域的合規性感興趣的讀者，可以在以下網站找到很多好的信息： ",-1)),l(e,{href:"https://refspecs.linuxfoundation.org/lsb.shtml"},{default:n(()=>[...t[0]||(t[0]=[s("Linux 基本標準（LSB）",-1)])]),_:1}),t[2]||(t[2]=s("。",-1))]),t[22]||(t[22]=i("h3",{id:"但我不是程序員或系統設計師",tabindex:"-1"},[s("但我不是程序員或系統設計師... "),i("a",{class:"header-anchor",href:"#但我不是程序員或系統設計師","aria-label":"Permalink to “但我不是程序員或系統設計師...”"},"​")],-1)),t[23]||(t[23]=i("p",null,"許多從事計算機工作的人並不是程序員或操作系統設計師。他們是醫院的文員，是寫信件、任務清單、聽寫備忘錄的秘書，等等。其他人則是將數字製成表格，收集和整理數據，經營網上商店，寫書和文章（我們中的一些人還會閲讀這些文章）。幾乎在每一個工作中，附近都可能有一台計算機。",-1)),t[24]||(t[24]=i("p",null,"POSIX 也影響着這些用户，不管他們是否知道。用户不一定要遵守這個標準，但他們確實希望他們的計算機能夠工作。當操作系統和程序符合 POSIX 標準時，他們就獲得了互操作性的好處。他們將能夠從一個系統轉移到另一個系統，併合理地期望這些機器能夠像另一個系統那樣工作。他們的數據仍然可以訪問，他們仍然能夠對其進行修改。",-1)),t[25]||(t[25]=i("p",null,"POSIX，以及其他標準，都在不斷發展。隨着技術的發展，標準也在發展。標準實際上是人們、製造商、組織等用來以有效的方式執行任務的商定系統。一個製造商的設備能夠與另一個製造商的設備一起工作。想一想吧。你的藍牙耳機可以在蘋果手機上使用，也可以在安卓手機上使用。我們的電視可以連接到不同網絡的視頻和節目，如 Amazon Prime、BritBox、Hulu —— 僅舉幾例。現在，我們甚至可以用我們的手機監測心率。所有這些在很大程度上都是通過遵守標準而實現的。",-1)),t[26]||(t[26]=i("p",null,"好處多多。我喜歡這樣。",-1)),t[27]||(t[27]=i("h3",{id:"那麼-x-是什麼",tabindex:"-1"},[s("那麼 “X” 是什麼？ "),i("a",{class:"header-anchor",href:"#那麼-x-是什麼","aria-label":"Permalink to “那麼 “X” 是什麼？”"},"​")],-1)),i("p",null,[t[4]||(t[4]=s("我承認，我還沒説過 POSIX 中的 “X” 是什麼意思。",-1)),l(e,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:n(()=>[...t[3]||(t[3]=[s("在一篇很好的文章中",-1)])]),_:1}),t[5]||(t[5]=s("，Richard Stallman 解釋了 POSIX 中的 “X” 是什麼意思。用他的話來説就是這樣：",-1))]),t[28]||(t[28]=i("blockquote",null,[i("p",null,"IEEE 已經完成了規範的制定，但沒有簡潔的名稱。標題是 “可移植的操作系統接口”，雖然我不記得確切的字眼了。委員會把 “IEEEIX” 作為簡寫。我不認為這是個好的選擇。它的發音很難聽 —— 聽起來就像恐怖的尖叫聲，“Ayeee！” —— 所以我預計人們會把這個規範叫為 “Unix”。"),i("p",null,"由於 GNU 不是 Unix，而它的目的是取代 Unix，我不希望人們把 GNU 稱為 “Unix 系統”。因此，我提出了一個人們可能真正使用的簡潔的名字。在沒有特別靈感的情況下，我用了一種很笨的方式取了一個名字。我取了 “可移植操作系統” 的首字母並加上 “ix”。IEEE 馬上就採用了這個名字。")],-1)),t[29]||(t[29]=i("h3",{id:"結論",tabindex:"-1"},[s("結論 "),i("a",{class:"header-anchor",href:"#結論","aria-label":"Permalink to “結論”"},"​")],-1)),t[30]||(t[30]=i("p",null,"POSIX 標準允許開發者使用大部分相同的代碼在許多操作系統上創建應用程序、工具和平台。不管怎麼説，按照標準寫代碼並不是一個要求，但當你想把你的代碼移植到其他系統時，它確實有很大的幫助。",-1)),t[31]||(t[31]=i("p",null,"基本上，POSIX 是面向操作系統設計者和軟件開發者的，但作為系統的使用者，無論我們是否意識到，我們都受到 POSIX 的影響。正是因為有了這個標準，我們才能夠在一個 UNIX 或 Linux 系統上工作，並把工作帶到另一個系統上，而且工作起來毫無障礙。作為用户，我們在可用性和跨系統的數據重複使用方面獲得了許多好處。",-1)),t[32]||(t[32]=i("hr",null,null,-1)),i("p",null,[t[7]||(t[7]=s("via: ",-1)),l(e,{href:"https://itsfoss.com/posix/"},{default:n(()=>[...t[6]||(t[6]=[s("https://itsfoss.com/posix/",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=s("作者：",-1)),l(e,{href:"https://itsfoss.com/author/bill/"},{default:n(()=>[...t[8]||(t[8]=[s("Bill Dyer",-1)])]),_:1}),t[13]||(t[13]=s(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[9]||(t[9]=[s("lujun9972",-1)])]),_:1}),t[14]||(t[14]=s(" 譯者：",-1)),l(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[10]||(t[10]=[s("wxy",-1)])]),_:1}),t[15]||(t[15]=s(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[11]||(t[11]=[s("wxy",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=s("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[16]||(t[16]=[s("LCTT",-1)])]),_:1}),t[19]||(t[19]=s(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:n(()=>[...t[17]||(t[17]=[s("Linux中國",-1)])]),_:1}),t[20]||(t[20]=s(" 榮譽推出",-1))])])}const b=o(u,[["render",X]]);export{U as __pageData,b as default};
